def solve(grid):
    """
    Looks for a 3×3 sub‑grid where all eight neighbour cells contain the same
    non‑zero value X and the centre cell contains a different value Y.
    Returns a 1×1 grid [[Y]]. If no such pattern is found, returns [[0]].
    """
    rows = len(grid)
    if rows < 3:
        return [[0]]
    cols = len(grid[0])
    if cols < 3:
        return [[0]]

    for i in range(rows - 2):
        for j in range(cols - 2):
            center = grid[i + 1][j + 1]
            # pick the first surrounding cell as the candidate uniform value X
            x = grid[i][j]
            if x == 0:          # we are only interested in non‑zero patterns
                continue
            # check that all eight neighbours equal x
            ok = True
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    if grid[i + 1 + dr][j + 1 + dc] != x:
                        ok = False
                        break
                if not ok:
                    break
            if ok and center != x:
                # found the required pattern
                return [[center]]

    # no 3×3 uniform block with a different centre was found
    return [[0]]

